ALTER TABLE "ExamAttempt" ADD COLUMN "deadlineAt" TIMESTAMP(3), ADD COLUMN "questionSnapshot" JSONB, ADD COLUMN "draftAnswers" JSONB NOT NULL DEFAULT '[]', ADD COLUMN "draftRevision" INTEGER NOT NULL DEFAULT 0;
UPDATE "ExamAttempt" a SET "questionSnapshot" = (SELECT jsonb_agg(to_jsonb(q) || jsonb_build_object('skills', COALESCE((SELECT jsonb_agg(jsonb_build_object('skillId', qs."skillId")) FROM "QuestionSkill" qs WHERE qs."questionId" = q.id), '[]'::jsonb)) ORDER BY array_position(a."questionIds",q.id)) FROM "Question" q WHERE q.id = ANY(a."questionIds")), "deadlineAt" = a."startedAt" + CASE a."examType" WHEN 'FULL' THEN interval '120 minutes' WHEN 'MINI' THEN interval '60 minutes' WHEN 'PART_5' THEN interval '20 minutes' ELSE make_interval(secs => (SELECT COALESCE(SUM(CASE WHEN q.part <= 4 THEN 27 ELSE 0 END),0)::int FROM "Question" q WHERE q.id = ANY(a."questionIds")) + CASE WHEN 5 = ANY(a."selectedParts") THEN 1200 ELSE 0 END + CASE WHEN 6 = ANY(a."selectedParts") THEN 600 ELSE 0 END + CASE WHEN 7 = ANY(a."selectedParts") THEN 2700 ELSE 0 END) END;
ALTER TABLE "ExamAnswer" DROP CONSTRAINT "ExamAnswer_questionId_fkey";
CREATE TABLE "MasteryOutbox" ("id" TEXT NOT NULL PRIMARY KEY, "payload" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "processedAt" TIMESTAMP(3), "attempts" INTEGER NOT NULL DEFAULT 0, "nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastError" TEXT);
CREATE INDEX "MasteryOutbox_processedAt_nextAttemptAt_idx" ON "MasteryOutbox"("processedAt", "nextAttemptAt");
CREATE TABLE "LearningAttempt" ("id" TEXT NOT NULL PRIMARY KEY,"userId" INTEGER NOT NULL,"kind" TEXT NOT NULL,"scopeId" INTEGER NOT NULL,"payloadHash" TEXT NOT NULL,"result" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);

ALTER TABLE "StudentSkillHistory" DROP CONSTRAINT "StudentSkillHistory_questionId_fkey";
